SS_ci_job_config.invariants_dsl:
spec CIJobConfig {
    field runner_os: String {
        value IN ["linux", "macos", "windows"];
    }
    field permission_level: String {
        value IN ["read", "write", "none"];
    }
    field timeout_minutes: Integer {
        value >= 1;
        value <= 360;
    }
    field max_parallel: Integer {
        value >= 1;
        value <= 256;
    }
}

SS_k8s_container_resources.invariants_dsl:
spec ContainerResources {
    field cpu_request_millicores: Integer {
        value >= 10;
        value <= 4000;
    }
    field cpu_limit_millicores: Integer {
        value >= this.cpu_request_millicores;
        value <= 8000;
    }
    field memory_request_mi: Integer {
        value >= 16;
        value <= 16384;
    }
    field memory_limit_mi: Integer {
        value >= this.memory_request_mi;
        value <= 32768;
    }
}

SS_aws_autoscaling_group.invariants_dsl:
spec AutoScalingGroup {
    field min_size: Integer {
        value >= 0;
        value <= 100;
    }
    field max_size: Integer {
        value >= this.min_size;
        value <= 200;
    }
    field desired_capacity: Integer {
        value >= this.min_size;
        value <= this.max_size;
    }
    field instance_tier: String {
        value IN ["small", "medium", "large", "xlarge"];
    }
}

SS_stripe_invoice.invariants_dsl:
spec Invoice {
    field subtotal_cents: Integer {
        value >= 100;
        value <= 10000000;
    }
    field tax_rate_pct: Number {
        value >= 0.0;
        value <= 25.0;
    }
    field tax_cents: Number {
        value == this.subtotal_cents * (this.tax_rate_pct / 100.0);
    }
    field total_cents: Number {
        value == this.subtotal_cents + this.tax_cents;
    }
    field amount_paid_cents: Number {
        value >= 0.0;
        value <= this.total_cents;
    }
    field amount_remaining_cents: Number {
        value == this.total_cents - this.amount_paid_cents;
    }
    field status: String {
        value IN ["draft", "open", "paid", "void", "uncollectible"];
    }
}

SS_geojson_feature.invariants_dsl:
spec GeoFeature {
    field geometry_type: String {
        value IN ["Point", "LineString", "Polygon", "MultiPoint", "MultiLineString", "MultiPolygon"];
    }
    field longitude: Number {
        value >= -180.0;
        value <= 180.0;
    }
    field latitude: Number {
        value >= -90.0;
        value <= 90.0;
    }
    field elevation_m: Number {
        value >= -11000.0;
        value <= 9000.0;
    }
}

SS_shipping_package.invariants_dsl:
spec ShippingPackage {
    field length_in: Number {
        value >= 1.0;
        value <= 108.0;
    }
    field width_in: Number {
        value >= 1.0;
        value <= 108.0;
    }
    field height_in: Number {
        value >= 1.0;
        value <= 108.0;
    }
    field actual_weight_lbs: Number {
        value >= 0.1;
        value <= 150.0;
    }
    field dimensional_weight_lbs: Number {
        value == (this.length_in * this.width_in * this.height_in) / 139.0;
    }
    field billable_weight_lbs: Number {
        value >= this.actual_weight_lbs;
        value >= this.dimensional_weight_lbs;
        value <= 1000.0;
    }
}
